using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capabilities to the research agent.
/// Uses the Google Custom Search JSON API.
/// Set environment variables GOOGLE_API_KEY and GOOGLE_SEARCH_ENGINE_ID to use a real search engine,
/// or leave them unset to use simulated results for demonstration.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly string? _apiKey;
    private readonly string? _searchEngineId;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _apiKey = Environment.GetEnvironmentVariable("GOOGLE_API_KEY");
        _searchEngineId = Environment.GetEnvironmentVariable("GOOGLE_SEARCH_ENGINE_ID");
    }

    [Description("Searches the web for information on a given query. Returns a list of results with titles, snippets, and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        if (!string.IsNullOrEmpty(_apiKey) && !string.IsNullOrEmpty(_searchEngineId))
        {
            return await SearchWithGoogleAsync(query, maxResults);
        }

        return GetSimulatedResults(query, maxResults);
    }

    private async Task<string> SearchWithGoogleAsync(string query, int maxResults)
    {
        var url = $"https://www.googleapis.com/customsearch/v1?key={_apiKey}&cx={_searchEngineId}&q={Uri.EscapeDataString(query)}&num={maxResults}";
        var response = await _httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
        var results = new List<object>();

        if (doc.RootElement.TryGetProperty("items", out var items))
        {
            foreach (var item in items.EnumerateArray())
            {
                results.Add(new
                {
                    title = item.GetProperty("title").GetString(),
                    snippet = item.GetProperty("snippet").GetString(),
                    url = item.GetProperty("link").GetString()
                });
            }
        }

        return results.Count > 0
            ? JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true })
            : "No results found.";
    }

    private static string GetSimulatedResults(string query, int maxResults)
    {
        var simulatedResults = new List<object>
        {
            new {
                title = $"Overview of {query} - Wikipedia",
                snippet = $"{query} is a broad topic with many facets. Recent research has shown significant advances in understanding its core principles and applications across multiple domains.",
                url = $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}"
            },
            new {
                title = $"Latest Developments in {query} - Science Daily",
                snippet = $"Scientists have made breakthrough discoveries related to {query}, publishing new findings that could reshape our understanding of the field.",
                url = $"https://www.sciencedaily.com/search/?keyword={Uri.EscapeDataString(query)}"
            },
            new {
                title = $"{query}: A Comprehensive Guide - Research Journal",
                snippet = $"This comprehensive guide covers the fundamentals of {query}, including historical context, current state of research, and future directions.",
                url = $"https://www.researchjournal.com/guide/{Uri.EscapeDataString(query)}"
            },
            new {
                title = $"Impact of {query} on Modern Society - The Atlantic",
                snippet = $"An in-depth analysis of how {query} is influencing technology, policy, and daily life in the modern world.",
                url = $"https://www.theatlantic.com/technology/{Uri.EscapeDataString(query)}"
            },
            new {
                title = $"Expert Opinions on {query} - Nature",
                snippet = $"Leading experts weigh in on the most pressing questions surrounding {query} and what the future holds.",
                url = $"https://www.nature.com/articles/{Uri.EscapeDataString(query)}"
            }
        };

        var results = simulatedResults.Take(maxResults).ToList();
        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using System.Text;
using System.Text.Json;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capabilities so the agent can collect
/// and organize research findings before producing a summary.
/// </summary>
public sealed class NoteTool
{
    private readonly List<NoteEntry> _notes = [];

    [Description("Saves a research note with a category tag. Use this to record key findings from web searches.")]
    public string SaveNote(
        [Description("A short category for the note (e.g., 'definition', 'statistics', 'expert_opinion')")] string category,
        [Description("The content of the note")] string content,
        [Description("The source URL where this information was found, if any")] string? sourceUrl = null)
    {
        var entry = new NoteEntry(category, content, sourceUrl, DateTime.UtcNow);
        _notes.Add(entry);
        return $"Note #{_notes.Count} saved under '{category}'.";
    }

    [Description("Retrieves all saved notes, optionally filtered by category.")]
    public string GetNotes(
        [Description("If provided, only return notes matching this category")] string? category = null)
    {
        var filtered = string.IsNullOrEmpty(category)
            ? _notes
            : _notes.Where(n => n.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return string.IsNullOrEmpty(category)
                ? "No notes have been saved yet."
                : $"No notes found for category '{category}'.";
        }

        var sb = new StringBuilder();
        for (int i = 0; i < filtered.Count; i++)
        {
            var note = filtered[i];
            sb.AppendLine($"--- Note #{i + 1} [{note.Category}] ---");
            sb.AppendLine(note.Content);
            if (!string.IsNullOrEmpty(note.SourceUrl))
                sb.AppendLine($"Source: {note.SourceUrl}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    [Description("Returns a count of notes by category to help plan the summary.")]
    public string GetNoteSummary()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var grouped = _notes
            .GroupBy(n => n.Category, StringComparer.OrdinalIgnoreCase)
            .Select(g => new { Category = g.Key, Count = g.Count() });

        return JsonSerializer.Serialize(new
        {
            totalNotes = _notes.Count,
            byCategory = grouped
        }, new JsonSerializerOptions { WriteIndented = true });
    }

    private sealed record NoteEntry(string Category, string Content, string? SourceUrl, DateTime Timestamp);
}

