using System.ComponentModel;
using System.Text;
using System.Text.Json;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capabilities so the agent can collect
/// and organize research findings before producing a summary.
/// </summary>
public sealed class NoteTool
{
    private readonly List<NoteEntry> _notes = [];

    [Description("Saves a research note with a category tag. Use this to record key findings from web searches.")]
    public string SaveNote(
        [Description("A short category for the note (e.g., 'definition', 'statistics', 'expert_opinion')")] string category,
        [Description("The content of the note")] string content,
        [Description("The source URL where this information was found, if any")] string? sourceUrl = null)
    {
        var entry = new NoteEntry(category, content, sourceUrl, DateTime.UtcNow);
        _notes.Add(entry);
        return $"Note #{_notes.Count} saved under '{category}'.";
    }

    [Description("Retrieves all saved notes, optionally filtered by category.")]
    public string GetNotes(
        [Description("If provided, only return notes matching this category")] string? category = null)
    {
        var filtered = string.IsNullOrEmpty(category)
            ? _notes
            : _notes.Where(n => n.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return string.IsNullOrEmpty(category)
                ? "No notes have been saved yet."
                : $"No notes found for category '{category}'.";
        }

        var sb = new StringBuilder();
        for (int i = 0; i < filtered.Count; i++)
        {
            var note = filtered[i];
            sb.AppendLine($"--- Note #{i + 1} [{note.Category}] ---");
            sb.AppendLine(note.Content);
            if (!string.IsNullOrEmpty(note.SourceUrl))
                sb.AppendLine($"Source: {note.SourceUrl}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    [Description("Returns a count of notes by category to help plan the summary.")]
    public string GetNoteSummary()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var grouped = _notes
            .GroupBy(n => n.Category, StringComparer.OrdinalIgnoreCase)
            .Select(g => new { Category = g.Key, Count = g.Count() });

        return JsonSerializer.Serialize(new
        {
            totalNotes = _notes.Count,
            byCategory = grouped
        }, new JsonSerializerOptions { WriteIndented = true });
    }

    private sealed record NoteEntry(string Category, string Content, string? SourceUrl, DateTime Timestamp);
}

