using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

builder.Logging.SetMinimumLevel(LogLevel.Warning);

builder.Services.AddHttpClient();

// Register the AI client — requires OPENAI_API_KEY env var
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseLogging()
    .UseOpenAIChatClient(modelId, apiKey));

using var host = builder.Build();

// Create tool instances
var httpClient = host.Services.GetRequiredService<IHttpClientFactory>().CreateClient();
var webSearch = new WebSearchTool(httpClient);
var notes = new NoteTool();

// Register tools via AIFunctionFactory
var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(notes.SaveNote),
    AIFunctionFactory.Create(notes.GetNotes),
    AIFunctionFactory.Create(notes.GetNoteSummary),
};

// Build the agent
var chatClient = host.Services.GetRequiredService<IChatClient>();
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to thoroughly research a topic using
        web searches, take organized notes on your findings, and then produce a
        well-structured summary.

        Follow this process:
        1. Search the web with varied queries to gather diverse perspectives on the topic.
        2. Save key findings as notes, categorizing them (e.g., "definition",
           "statistics", "expert_opinion", "history", "future_outlook").
        3. After gathering enough information (at least 3-4 searches), review your
           notes and produce a comprehensive summary.

        Your final summary should include:
        - An overview of the topic
        - Key findings organized by theme
        - Notable expert opinions or data points
        - Sources cited with URLs

        Be thorough but concise. Focus on factual, well-sourced information.
        """,
};

// Get the topic from the user
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");
Console.WriteLine("The agent is searching the web and taking notes...\n");

// Run the agent
var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        Tools = tools,
    }
};

await foreach (var response in agent.InvokeStreamingAsync(messages, options))
{
    if (response.Role == ChatRole.Assistant && !string.IsNullOrEmpty(response.Text))
    {
        Console.Write(response.Text);
    }
}

Console.WriteLine("\n\n✅ Research complete.");

